import copy
import hmac
from collections.abc import Iterable, Mapping


def _normalize_users(users):
    if not isinstance(users, Mapping):
        raise ValueError("users must be a mapping")
    result = {}
    for name, record in users.items():
        if not isinstance(name, str) or not name:
            raise ValueError("invalid username")
        if not isinstance(record, Mapping) or set(record) != {"secret", "groups"}:
            raise ValueError("invalid user record")
        secret = record["secret"]
        groups = record["groups"]
        if not isinstance(secret, str) or isinstance(groups, (str, bytes)) or not isinstance(groups, Iterable):
            raise ValueError("invalid user record")
        normalized_groups = set()
        for group in groups:
            if not isinstance(group, str) or not group:
                raise ValueError("invalid group")
            normalized_groups.add(group)
        result[name] = {"secret": secret, "groups": normalized_groups}
    return result


def _normalize_rules(rules):
    if not isinstance(rules, Mapping):
        raise ValueError("rules must be a mapping")
    result = {}
    for resource, groups in rules.items():
        if not isinstance(resource, str) or not resource:
            raise ValueError("invalid resource")
        if isinstance(groups, (str, bytes)) or not isinstance(groups, Iterable):
            raise ValueError("invalid rule")
        normalized_groups = set()
        for group in groups:
            if not isinstance(group, str) or not group:
                raise ValueError("invalid group")
            normalized_groups.add(group)
        result[resource] = normalized_groups
    return result


class PolicyStore:
    def __init__(self, users, rules):
        self._users = _normalize_users(copy.deepcopy(users))
        self._rules = _normalize_rules(copy.deepcopy(rules))

    def authenticate(self, username, secret):
        if not isinstance(username, str) or not isinstance(secret, str):
            return False
        record = self._users.get(username)
        return record is not None and hmac.compare_digest(record["secret"], secret)

    def groups_for(self, username):
        record = self._users.get(username)
        return tuple(sorted(record["groups"])) if record else ()

    def is_allowed(self, username, resource):
        record = self._users.get(username)
        if record is None:
            return False
        if resource not in self._rules:
            return False
        if "admin" in record["groups"]:
            return True
        return bool(record["groups"] & self._rules.get(resource, set()))

    def replace_users(self, users):
        replacement = _normalize_users(copy.deepcopy(users))
        self._users = replacement

    def replace_rules(self, rules):
        replacement = _normalize_rules(copy.deepcopy(rules))
        self._rules = replacement

    def snapshot(self):
        users = {
            name: {
                "secret": record["secret"],
                "groups": sorted(record["groups"]),
            }
            for name, record in self._users.items()
        }
        rules = {
            resource: sorted(groups)
            for resource, groups in self._rules.items()
        }
        return copy.deepcopy({"users": users, "rules": rules})

